{
  "items": [
    {
      "title": "GESIS – Landtagswahl im Saarland 2012 (ZA5642)",
      "url_or_doi": "https://www.gesis.org/wahlen/landtagswahlen",
      "justification": "A Saarland-specific election study covering the state parliamentary election of March 25, 2012. Archived by GESIS under study number ZA5642, it is particularly relevant for investigating electoral behavior, party preferences, and political attitudes during the early 2010s. The GESIS landing page provides access to the study catalogue and documentation. Researchers should consult the study metadata for the available questionnaire variables, geographic detail, and access conditions."
    },
    {
      "title": "GESIS – Landtagswahl im Saarland 2017 (ZA6948)",
      "url_or_doi": "https://www.gesis.org/wahlen/landtagswahlen",
      "justification": "A Saarland-specific election study associated with the state parliamentary election of March 26, 2017, archived by GESIS under study number ZA6948. Particularly useful for examining voting decisions, party support, and political attitudes in Saarland during the late 2010s. Together with the 2012 study, it provides a foundation for comparing electoral behavior across two state elections. The precise survey variables and availability of individual-level data should be checked in the GESIS catalogue."
    },
    {
      "title": "German General Social Survey (ALLBUS), 2010–2018",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "ALLBUS is a major German social survey conducted approximately every two years. Its 2010, 2012, 2014, 2016, and 2018 waves contain information on political participation, political interest, party preferences, institutional trust, democratic attitudes, social values, and demographic characteristics. The ALLBUS Extended datasets include federal-state identifiers, allowing researchers to identify respondents living in Saarland. This makes the series especially useful for studying changes in political attitudes throughout the 2010s. However, Saarland subsamples may be relatively small, and access to detailed regional variables requires additional arrangements."
    },
    {
      "title": "ALLBUS Cumulation 1980–2018 (ZA5274)",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "This cumulative dataset combines multiple waves of the German General Social Survey, including surveys conducted throughout the 2010s. It contains repeated measures of political and social attitudes, enabling longitudinal comparisons of population-level trends. Researchers can focus on the 2010–2018 period and, where appropriate regional identifiers are accessible, examine Saarland separately. Particularly valuable for investigating changes in political trust, democratic satisfaction, political participation, and ideological orientation. The cumulative structure facilitates consistent comparisons across survey years."
    },
    {
      "title": "German Longitudinal Election Study (GLES), 2009–2017",
      "url_or_doi": "https://www.gesis.org/en/elections",
      "justification": "The German Longitudinal Election Study collects extensive information about electoral behavior, political attitudes, party identification, candidate evaluations, political knowledge, and campaign influences. Survey waves surrounding the 2013 and 2017 German federal elections are particularly relevant to the requested decade. Depending on the dataset and geographic identifiers available, researchers may be able to analyze respondents from Saarland. The study is especially suitable for examining how political preferences and voting behavior developed during the 2010s. Geographic coverage and sample sizes should be verified before undertaking Saarland-specific analysis."
    },
    {
      "title": "Politbarometer – German Political Opinion Surveys",
      "url_or_doi": "https://www.gesis.org/en/elections",
      "justification": "Politbarometer is a long-running series of German political opinion surveys archived by GESIS. Its 2010s surveys provide information about voting intentions, political preferences, evaluations of political leaders, party competence, and attitudes toward current political issues. The series is useful for investigating changes in political opinion around the 2012 and 2017 Saarland elections. Researchers should verify which survey waves contain identifiable Saarland respondents, as geographic detail and regional sample sizes may vary."
    },
    {
      "title": "DeutschlandTREND – Political Opinion Surveys, 2010–2019",
      "url_or_doi": "https://www.gesis.org/en/elections",
      "justification": "DeutschlandTREND surveys provide repeated measurements of German public opinion, including political attitudes, party support, evaluations of government performance, and assessments of political issues. Surveys conducted throughout the 2010s can help contextualize political developments in Saarland within broader German trends. The series is archived through the GESIS Research Data Center Elections. Saarland-specific analysis depends on the availability of regional identifiers and sufficiently large state-level samples."
    },
    {
      "title": "Saarland State Election Polling Data, 2010–2017 – Wahlrecht.de",
      "url_or_doi": "https://www.wahlrecht.de/umfragen/landtage/saarland.htm",
      "justification": "This publicly accessible collection contains historical voting-intention polls for Saarland state elections, including polling conducted during 2010, 2011, 2012, and the period leading up to the 2017 election. It reports party support percentages, polling organizations, fieldwork dates, and sample-size information where available. The data are particularly useful for analyzing changes in electoral preferences, party competition, and public opinion during the 2010s. Unlike individual-level survey datasets, this resource primarily provides aggregated polling results."
    },
    {
      "title": "Saarland State Parliamentary Election Results – Municipal-Level Electoral Statistics",
      "url_or_doi": "https://www.govdata.de/suche?sourceportal=1e17f560-2061-4219-a37d-61e2fce75336&state=10&type=dataset",
      "justification": "The German open-data portal GovData indexes official Saarland election statistics, including a dataset covering eligible voters, electoral participation, and valid votes by political party at the municipal level through 2017. This resource is especially relevant for comparing the 2012 and 2017 state elections, identifying geographic differences in party support, and analyzing voter turnout across Saarland municipalities. Unlike opinion surveys, these are administrative election results rather than self-reported attitudes. The linked page is a Saarland dataset search landing page."
    },
    {
      "title": "Infratest dimap – WahlREPORT Saarland 2012",
      "url_or_doi": "https://www.infratest-dimap.de/umfragen-analysen/bundeslaender/saarland/wahlreport/",
      "justification": "The 2012 Saarland WahlREPORT provides an election-focused analysis drawing on polling and electoral data surrounding the March 25, 2012 state election. It examines voting patterns, electoral shifts, party performance, and differences between demographic and regional groups. The underlying pre-election polling included approximately 1,000 respondents. The report is valuable for studying electoral motivations and party preferences at the beginning of the decade. It is an analytical data publication rather than a confirmed downloadable individual-level dataset, and full access may require purchase."
    },
    {
      "title": "Infratest dimap – WahlREPORT Saarland 2017",
      "url_or_doi": "https://www.infratest-dimap.de/umfragen-analysen/bundeslaender/saarland/wahlreport/",
      "justification": "This election report analyzes the Saarland parliamentary election held on March 26, 2017. It provides quantitative findings concerning electoral behavior, party performance, voting patterns, and demographic differences in political preferences. It is particularly useful for investigating political attitudes and electoral changes during the second half of the 2010s. Comparing the 2017 and 2012 WahlREPORT publications can help identify changes in the Saarland electorate. The landing page provides information about the reports, although access to complete datasets or detailed analyses may be restricted."
    },
    {
      "title": "GESIS Research Data Center Elections – German State Election Studies, 1962–Present",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "The GESIS Research Data Center Elections maintains an extensive collection of German electoral studies, including state election surveys dating back to 1962. Its holdings include the Saarland election studies from 2012 and 2017, alongside national political opinion surveys and election research. The collection is particularly valuable for identifying individual-level datasets on voting behavior, political preferences, electoral participation, and party identification. It also provides a centralized starting point for obtaining documentation and checking data access requirements. This is a research data collection landing page rather than a single dataset."
    }
  ]
}
